mapper.select:
SELECT *
FROM mq_outbox
WHERE event_type = #{eventType}
  AND (
      consume_status IN (#{initStatus}, #{failedStatus})
      OR (consume_status = #{lockedStatus} AND lock_until <= #{now})
  )
  AND next_retry_at <= #{now}
  AND (lock_until IS NULL OR lock_until <= #{now})
ORDER BY next_retry_at ASC, id ASC
LIMIT #{limit}
